function draw(ctx, t, W, H) {
  ctx.save();
  ctx.fillStyle = '#f5f0e8';
  ctx.fillRect(0, 0, W, H);
  ctx.lineWidth = 4;
  ctx.strokeStyle = 'black';

  // sun
  ctx.fillStyle = 'yellow';
  ctx.beginPath();
  ctx.arc(W/2, H/2, 50 + 20*Math.sin(t), 0, 2*Math.PI);
  ctx.fill();
  ctx.stroke();

  // clouds
  ctx.fillStyle = 'white';
  for (let i = 0; i < 5; i++) {
    ctx.beginPath();
    ctx.arc(W/2 + 100*Math.cos(t + i), H/2 + 50*Math.sin(t + i), 20 + 10*Math.sin(t + i), 0, 2*Math.PI);
    ctx.fill();
    ctx.stroke();
  }

  // trees
  ctx.fillStyle = 'green';
  ctx.beginPath();
  ctx.rect(W/2 - 100, H - 50, 20, 50 + 20*Math.sin(t));
  ctx.fill();
  ctx.stroke();

  ctx.beginPath();
  ctx.rect(W/2 + 50, H - 50, 20, 50 + 20*Math.sin(t + Math.PI/2));
  ctx.fill();
  ctx.stroke();

  // birds
  ctx.fillStyle = 'black';
  ctx.beginPath();
  ctx.arc(W/2 + 150*Math.cos(t), H/2 - 50*Math.sin(t), 10, 0, 2*Math.PI);
  ctx.fill();
  ctx.stroke();

  ctx.beginPath();
  ctx.arc(W/2 + 150*Math.cos(t + Math.PI), H/2 - 50*Math.sin(t + Math.PI), 10, 0, 2*Math.PI);
  ctx.fill();
  ctx.stroke();

  ctx.restore();
}
